const item = $input.first().json;

// Transform Gmail raw response to Common Mail Message Schema
const headers = item.payload?.headers || [];
function getHeader(name) {
  const h = headers.find(x => x.name.toLowerCase() === name.toLowerCase());
  return h ? h.value : null;
}

const fromHeader = getHeader('From') || item.from || '';
const toHeader = getHeader('To') || item.to || '';
const ccHeader = getHeader('Cc') || item.cc || '';
const subject = getHeader('Subject') || item.snippet || '(Başlıksız E-posta)';
const dateHeader = getHeader('Date') || item.internalDate;
const messageIdHeader = getHeader('Message-ID') || getHeader('Message-Id');

const commonMessage = {
  provider: 'GMAIL',
  mailbox_address: 'eldornisoai@gmail.com',
  provider_message_id: item.id,
  provider_thread_id: item.threadId,
  internet_message_id: messageIdHeader,
  from_address: fromHeader,
  from_name: fromHeader.split('<')[0].trim().replace(/"/g, ''),
  to_addresses: toHeader ? toHeader.split(',').map(s => s.trim()) : [],
  cc_addresses: ccHeader ? ccHeader.split(',').map(s => s.trim()) : [],
  bcc_visible: false,
  reply_to_address: getHeader('Reply-To'),
  subject: subject,
  received_at: dateHeader ? new Date(dateHeader).toISOString() : new Date().toISOString(),
  sent_at: dateHeader ? new Date(dateHeader).toISOString() : new Date().toISOString(),
  in_reply_to: getHeader('In-Reply-To'),
  references: getHeader('References'),
  labels_or_categories: item.labelIds || [],
  plain_text_body: item.snippet || '',
  html_body: item.html || '',
  attachment_metadata: (item.attachments || []).map(att => ({
    filename: att.filename,
    mime_type: att.mimeType,
    size: att.size,
    attachment_id: att.attachmentId
  })),
  raw_metadata: {
    history_id: item.historyId,
    size_estimate: item.sizeEstimate
  },
  source_trigger: 'GMAIL_POLLING',
  ingested_at: new Date().toISOString()
};

return [{ json: commonMessage }];
